function validate([image, threshold]) {
  if (!Array.isArray(image) || image.length < 3 || image.length > 500) return 'image needs 3 to 500 rows.';
  const n = image[0].length;
  if (n < 3 || n > 500) return 'image needs 3 to 500 columns.';
  for (const row of image) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row of image must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 255)) return 'Each pixel is an integer from 0 to 255.';
  }
  if (!Number.isInteger(threshold) || threshold < 0 || threshold > 255) return 'threshold is an integer from 0 to 255.';
  return null;
}

