function resultGrid(image, threshold) {
  const rows = image.length;
  const cols = image[0].length;
  const total = Array.from({ length: rows }, () => new Array(cols).fill(0));
  const count = Array.from({ length: rows }, () => new Array(cols).fill(0));

  const isRegion = (top, left) => {
    for (let i = top; i < top + 3; i++) {
      for (let j = left; j < left + 3; j++) {
        if (i + 1 < top + 3 && Math.abs(image[i][j] - image[i + 1][j]) > threshold) return false;
        if (j + 1 < left + 3 && Math.abs(image[i][j] - image[i][j + 1]) > threshold) return false;
      }
    }
    return true;
  };

  for (let top = 0; top + 3 <= rows; top++) {
    for (let left = 0; left + 3 <= cols; left++) {
      if (!isRegion(top, left)) continue;
      let sum = 0;
      for (let i = top; i < top + 3; i++) {
        for (let j = left; j < left + 3; j++) sum += image[i][j];
      }
      const average = Math.floor(sum / 9);
      for (let i = top; i < top + 3; i++) {
        for (let j = left; j < left + 3; j++) {
          total[i][j] += average;
          count[i][j]++;
        }
      }
    }
  }

  return image.map((row, i) => row.map((pixel, j) => count[i][j] === 0 ? pixel : Math.floor(total[i][j] / count[i][j])));
}

