function resultGrid(image, threshold) {
  const m = image.length, n = image[0].length;
  const cellsOf = (r, c) => {
    const cells = [];
    for (let dr = 0; dr < 3; dr++) for (let dc = 0; dc < 3; dc++) cells.push([r + dr, c + dc]);
    return cells;
  };
  const ok = (r, c) => {
    const cells = cellsOf(r, c);
    for (const [a, b] of cells) for (const [x, y] of cells) {
      if (Math.abs(a - x) + Math.abs(b - y) === 1 && Math.abs(image[a][b] - image[x][y]) > threshold) return false;
    }
    return true;
  };
  const out = [];
  for (let i = 0; i < m; i++) {
    const line = [];
    for (let j = 0; j < n; j++) {
      const values = [];
      for (let r = i - 2; r <= i; r++) for (let c = j - 2; c <= j; c++) {
        if (r < 0 || c < 0 || r + 2 >= m || c + 2 >= n || !ok(r, c)) continue;
        values.push(Math.floor(cellsOf(r, c).reduce((s, [a, b]) => s + image[a][b], 0) / 9));
      }
      line.push(values.length === 0 ? image[i][j] : Math.floor(values.reduce((s, v) => s + v, 0) / values.length));
    }
    out.push(line);
  }
  return out;
}

