function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'large' ? int(90, 100) : int(3, 6);
  const n = size === 'large' ? int(90, 100) : int(3, 6);
  const style = rand();
  const step = style < 0.2 ? 0 : style < 0.6 ? int(1, 6) : style < 0.85 ? int(5, 30) : 255;
  const image = [];
  for (let i = 0; i < m; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      let base;
      if (i === 0 && j === 0) base = int(0, 255);
      else if (i === 0) base = row[j - 1];
      else if (j === 0) base = image[i - 1][0];
      else base = rand() < 0.5 ? row[j - 1] : image[i - 1][j];
      row.push(Math.max(0, Math.min(255, base + int(-step, step))));
    }
    image.push(row);
  }
  const pick = rand();
  const threshold = pick < 0.1 ? 255 : pick < 0.2 ? 0 : int(Math.min(255, step), Math.min(255, step * 3));
  return [image, threshold];
}
